class Solution {
public:
    int longestCycle(std::vector<int>& edges) {
        int n = edges.size();
        std::vector<bool> visited(n, false);
        int ans = -1;
        for (int i = 0; i < n; ++i) {
            if (visited[i]) continue;
            int cur = i, step = 1;
            std::unordered_map<int, int> dist;
            while (cur != -1) {
                if (dist.count(cur)) {
                    ans = std::max(ans, step - dist[cur]);
                    break;
                }
                if (visited[cur]) break;
                visited[cur] = true;
                dist[cur] = step++;
                cur = edges[cur];
            }
        }
        return ans;
    }
};

class Solution {
    public int longestCycle(int[] edges) {
        int n = edges.length;
        boolean[] visited = new boolean[n];
        int ans = -1;
        for (int i = 0; i < n; ++i) {
            if (visited[i]) continue;
            int cur = i, step = 1;
            java.util.Map<Integer, Integer> dist = new java.util.HashMap<>();
            while (cur != -1) {
                if (dist.containsKey(cur)) {
                    ans = Math.max(ans, step - dist.get(cur));
                    break;
                }
                if (visited[cur]) break;
                visited[cur] = true;
                dist.put(cur, step++);
                cur = edges[cur];
            }
        }
        return ans;
    }
}

